package org.mockito;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.matchers.*;
import org.mockito.internal.matchers.apachecommons.ReflectionEquals;
import org.mockito.internal.progress.HandyReturnValues;
import org.mockito.internal.progress.MockingProgress;
import org.mockito.internal.progress.ThreadSafeMockingProgress;
import static org.junit.Assert.*;
import static org.mockito.Matchers.same;

public class Matchers_same_TriageGen0Test {

    @Test
    public void testSame_String() {
        String input = "testValue";
        // Since the implementation calls reportMatcher(...).<T>returnNull(),
        // the returned value is expected to be null.
        String result = same(input);
        assertNull("The method is designed to return null after reporting the matcher", result);
    }

    @Test
    public void testSame_Integer() {
        Integer input = 123;
        Integer result = same(input);
        assertNull("The method is designed to return null after reporting the matcher", result);
    }

    @Test
    public void testSame_CustomObject() {
        Object input = new Object();
        Object result = same(input);
        assertNull("The method is designed to return null after reporting the matcher", result);
    }

    @Test
    public void testSame_NullValue() {
        Object input = null;
        Object result = same(input);
        assertNull("The method should handle null input and return null", result);
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testSame_GenericsTypeSafety() {
        // Testing that the generic type T is preserved in the signature 
        // even if the runtime value is null
        Double result = same(1.0);
        assertNull(result);
    }
}
